(()=>{const buttons=[...document.querySelectorAll('[data-filter]')],events=[...document.querySelectorAll('.history-event')];buttons.forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;buttons.forEach(b=>{const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});let count=0;events.forEach(event=>{event.hidden=filter!=='All'&&event.dataset.category!==filter;if(!event.hidden)count++});document.getElementById('history-count').textContent=count+' '+(count===1?'milestone':'milestones')+' · oldest first'}))})();
